var lantern = get_tree().get_first_node_in_group('lantern')
var inv = get_tree().get_first_node_in_group('player_inventory')
var before = {'wood': inv.get_bag_amount(9), 'stone': inv.get_bag_amount(2), 'level': lantern.level, 'r': lantern.get_safe_radius_tiles()}
var missing_try = lantern.try_upgrade(inv)
if bool(missing_try.get('ok', false)):
	pass
var after = {'wood': inv.get_bag_amount(9), 'stone': inv.get_bag_amount(2), 'level': lantern.level, 'r': lantern.get_safe_radius_tiles(), 'result': missing_try}
return {'before': before, 'after': after}
